{"code":"const start = new Date("2000-05-01T00:00:00Z");
const end = new Date("2000-06-01T00:00:00Z");
const results = [];
let total = 0;
for (let d = new Date(start); d < end; d = new Date(d.getTime() + 86400000)) {
  const a = d.toISOString().slice(0, 10);
  const b = new Date(d.getTime() + 86400000).toISOString().slice(0, 10);
  const r = corpus.grep("Dynegy", { after: a, before: b, limit: 1 });
  results.push([a, r.totalFiles]);
  total += r.totalFiles;
}
results.sort((x, y) => y[1] - x[1]);
console.log("total", total);
console.log(JSON.stringify(results.slice(0, 10)));
"}

